package pl.pitsmich.forma;

/** Short, offline quick-reference instructions for built-in exercises. */
public final class ExerciseGuides {
    private ExerciseGuides() {}
    public static String forId(String id,String fallback) {
        if(id==null)return fallback==null?"":fallback;
        switch(id) {
            case "db_flat": return "USTAWIENIE: Ustaw ławkę płasko; stopy stabilnie na podłodze. Ściągnij łopatki lekko do siebie i w dół.\n\nRUCH: Opuszczaj hantle po bokach klatki, przedramiona możliwie pionowo. Wyciskaj w górę bez zderzania hantli.\n\nODDECH: Wdech przy opuszczaniu, wydech przy wyciskaniu.\n\nUNIKAJ: Nie odrywaj pośladków ani nie rozstawiaj łokci idealnie na boki.";
            case "lat_wide": return "USTAWIENIE: Ustaw blokadę ud, usiądź wysoko i chwyć drążek nieco szerzej niż barki. Utrzymaj uniesioną klatkę.\n\nRUCH: Najpierw opuść barki, potem prowadź łokcie w dół do boków tułowia; drążek do górnej klatki. Powoli oddaj ruch.\n\nODDECH: Wydech przy ściąganiu, wdech w powrocie.\n\nUNIKAJ: Nie ciągnij za kark i nie pomagaj sobie odchylaniem całego ciała.";
            case "lat_close": return "USTAWIENIE: Zablokuj uda i chwyć uchwyt neutralnie — dłonie skierowane do siebie. Usiądź stabilnie.\n\nRUCH: Prowadź łokcie w dół i lekko do tyłu, kierując uchwyt do górnej klatki. Powracaj bez utraty kontroli.\n\nODDECH: Wydech przy ściąganiu, wdech przy prostowaniu ramion.\n\nUNIKAJ: Nie podrywaj bioder ani nie szarp linką.";
            case "lat_one": return "USTAWIENIE: Ustaw bloczek wysoko i złap uchwyt jedną ręką; stań lub uklęknij stabilnie.\n\nRUCH: Prowadź łokieć w stronę biodra, bez skrętu tułowia; oddaj rękę powoli w górę.\n\nODDECH: Wydech w przyciąganiu, wdech w powrocie.\n\nUNIKAJ: Nie przenoś pracy na obrót całego tułowia.";
            case "row_cable": return "USTAWIENIE: Usiądź z podpartymi stopami; ugnij lekko kolana. Utrzymaj naturalną pozycję pleców i barki nisko.\n\nRUCH: Prowadź łokcie w tył, przyciągając uchwyt do dolnych żeber lub nadbrzusza. Wróć aż łopatki swobodnie się wysuną.\n\nODDECH: Wydech podczas przyciągania, wdech w powrocie.\n\nUNIKAJ: Nie bujaj tułowiem ani nie zaokrąglaj mocno odcinka lędźwiowego.";
            case "straight_arm": return "USTAWIENIE: Ustaw bloczek wysoko. Stań krok od wyciągu, lekko zegnij kolana i pochyl się minimalnie w biodrach.\n\nRUCH: Przy prawie stałym, delikatnym zgięciu łokci prowadź drążek lub linę po łuku do ud. Powoli wróć ku górze.\n\nODDECH: Wydech w dół, wdech w górę.\n\nUNIKAJ: Nie zamieniaj ruchu w prostowanie łokci lub zamach tułowiem.";
            case "smith_incline": return "USTAWIENIE: Ustaw ławkę pod kątem około 15–30° i sprawdź tor gryfu bez obciążenia. Stopy i pośladki stabilnie; łopatki oparte.\n\nRUCH: Opuszczaj gryf w okolice górnej klatki w wygodnym zakresie, następnie wyciśnij płynnie do góry.\n\nODDECH: Wdech w dół, wydech w górę.\n\nUNIKAJ: Nie ustawiaj ławki zbyt stromo i sprawdź haki oraz ograniczniki Smitha.";
            case "chest_press": return "USTAWIENIE: Ustaw wysokość siedziska tak, aby uchwyty były mniej więcej na wysokości środka klatki. Oprzyj plecy i stopy.\n\nRUCH: Wypychaj uchwyty do przodu bez unoszenia barków; wracaj wolno, pozwalając łokciom na wygodny zakres.\n\nODDECH: Wydech przy wypychaniu, wdech w powrocie.\n\nUNIKAJ: Nie odrywaj pleców od oparcia i nie blokuj łokci gwałtownie.";
            case "butterfly": return "USTAWIENIE: Ustaw siedzisko tak, aby dłonie lub poduszki były na wysokości klatki. Utrzymaj plecy przy oparciu.\n\nRUCH: Zbliżaj ramiona przed klatką z lekko zgiętymi łokciami, następnie otwieraj wolno w komfortowym zakresie.\n\nODDECH: Wydech przy zamykaniu, wdech przy otwieraniu.\n\nUNIKAJ: Nie rozciągaj barków na siłę i nie wysuwaj głowy do przodu.";
            case "leg_press": return "USTAWIENIE: Ustaw siedzisko i zakres tak, aby całe stopy opierały się o platformę mniej więcej na szerokość barków.\n\nRUCH: Prowadź kolana w kierunku palców stóp; uginaj je tylko tak głęboko, aby miednica nie odrywała się od oparcia. Wypychaj przez całe stopy.\n\nODDECH: Wdech w dół, wydech przy wypychaniu.\n\nUNIKAJ: Nie odrywaj pięt, nie zapadaj kolan do środka i nie blokuj ich gwałtownie.";
            case "leg_curl": return "USTAWIENIE: Ustaw oś maszyny zgodnie z kolanem, wałek nad dolną częścią podudzi; zabezpiecz uda poduszką.\n\nRUCH: Ugnij kolana płynnie, utrzymaj biodra przy siedzisku. Powoli prostuj nogi do wyjściowej pozycji.\n\nODDECH: Wydech przy uginaniu, wdech przy powrocie.\n\nUNIKAJ: Nie unoś bioder i nie odbijaj ciężaru na końcu ruchu.";
            case "leg_ext": return "USTAWIENIE: Ustaw kolana na wysokości osi obrotu maszyny i wałek tuż nad stopami; oprzyj plecy.\n\nRUCH: Wyprostuj kolana płynnie w komfortowym zakresie, zatrzymaj na moment i opuść ciężar pod kontrolą.\n\nODDECH: Wydech przy prostowaniu, wdech przy opuszczaniu.\n\nUNIKAJ: Nie szarp ciężarem ani nie odrywaj pośladków od siedziska.";
            case "rev_lunge": return "USTAWIENIE: Stań prosto z hantlami po bokach, stopy na szerokość bioder. Zachowaj stabilny brzuch.\n\nRUCH: Zrób kontrolowany krok w tył, zegnij oba kolana w wygodnym zakresie, wróć naciskając głównie nogą z przodu.\n\nODDECH: Wdech w dół, wydech przy powrocie.\n\nUNIKAJ: Nie stawiaj stóp na jednej linii jak na linie; w razie utraty równowagi zmniejsz ciężar.";
            case "cable_lateral": return "USTAWIENIE: Ustaw bloczek nisko, stań bokiem do wyciągu i chwyć rączkę dalszą ręką; łokieć delikatnie ugięty.\n\nRUCH: Unieś ramię bokiem do okolicy wysokości barku, prowadząc łokieć i dłoń płynnie. Opuść wolniej niż unosisz.\n\nODDECH: Wydech przy unoszeniu, wdech przy opuszczaniu.\n\nUNIKAJ: Nie wzruszaj barkiem ani nie przechylaj tułowia, żeby podnieść więcej.";
            case "db_lateral": return "USTAWIENIE: Stań stabilnie z hantlami przy udach, łokcie lekko ugięte, barki opuszczone.\n\nRUCH: Unoś ramiona na boki do około wysokości barków i kontroluj opuszczanie.\n\nODDECH: Wydech przy unoszeniu, wdech przy powrocie.\n\nUNIKAJ: Nie bujaj tułowiem i nie podciągaj ciężaru kapturami.";
            case "facepull": return "USTAWIENIE: Ustaw linę mniej więcej na wysokości twarzy, cofnij się tak, by linka była napięta. Stabilna postawa.\n\nRUCH: Ciągnij końce liny ku skroniom lub czołu, rozdzielając dłonie i prowadząc łokcie na boki. Powoli prostuj ramiona.\n\nODDECH: Wydech przy przyciąganiu, wdech przy powrocie.\n\nUNIKAJ: Nie unoś barków ani nie odchylaj się gwałtownie.";
            case "tri_push": return "USTAWIENIE: Ustaw bloczek wysoko, stań stabilnie i złap końce liny. Łokcie trzymaj blisko boków ciała.\n\nRUCH: Prostuj łokcie w dół, na dole lekko rozdziel końce liny. Wróć powoli, nie przesuwając ramion.\n\nODDECH: Wydech przy prostowaniu, wdech w powrocie.\n\nUNIKAJ: Nie kołysz tułowiem ani nie wypychaj łokci do przodu.";
            case "tri_overhead": return "USTAWIENIE: Ustaw linę na wyciągu i stań stabilnie z lekkim pochyleniem. Ustaw ramiona przy głowie, łokcie ugięte.\n\nRUCH: Prostuj łokcie, utrzymując ramiona możliwie nieruchomo; następnie wracaj do wygodnego rozciągnięcia.\n\nODDECH: Wydech przy prostowaniu, wdech przy uginaniu.\n\nUNIKAJ: Nie wyginaj pleców i nie rozsuwaj łokci przesadnie.";
            case "bi_cable": return "USTAWIENIE: Ustaw dolny bloczek, stań stabilnie i chwyć uchwyt podchwytem lub neutralnie, zależnie od wariantu.\n\nRUCH: Uginasz łokcie, prowadząc dłonie ku barkom, bez przemieszczania ramion; opuszczaj ciężar wolno.\n\nODDECH: Wydech przy zginaniu, wdech przy opuszczaniu.\n\nUNIKAJ: Nie odchylaj tułowia ani nie podrzucaj ciężaru biodrami.";
            case "calf_standing": return "USTAWIENIE: Stań na podwyższeniu lub platformie maszyny, śródstopie stabilnie oparte, kolana lekko odblokowane.\n\nRUCH: Opuszczaj pięty do łagodnego rozciągnięcia łydki, następnie wspinaj się wysoko na palce z krótką pauzą.\n\nODDECH: Wydech przy wspięciu, wdech przy opuszczaniu.\n\nUNIKAJ: Nie sprężynuj z dołu i nie przenoś stóp na zewnętrzne krawędzie.";
            case "calf_seated": return "USTAWIENIE: Ustaw poduszki nad udami, stopy oprzyj śródstopiem na platformie, kolana zgięte.\n\nRUCH: Powoli opuść pięty, następnie unieś je jak najwyżej bez odbijania ciężaru. Zrób krótką pauzę na górze.\n\nODDECH: Wydech w górę, wdech w dół.\n\nUNIKAJ: Nie podrywaj ud spod poduszek.";
            case "calf": return "USTAWIENIE: Ustaw śródstopie stabilnie na platformie; ugnij kolana tylko tyle, ile wymaga wariant maszyny.\n\nRUCH: Opuszczaj pięty powoli, a potem wspinaj się na palce do pełnego komfortowego zakresu.\n\nODDECH: Wydech na wspięciu, wdech w powrocie.\n\nUNIKAJ: Nie odbijaj się dynamicznie w dolnej pozycji.";
            case "ab_crunch": return "USTAWIENIE: Dopasuj siedzisko i uchwyty tak, aby oś maszyny pozwalała wygodnie zgiąć tułów. Ustaw miednicę stabilnie.\n\nRUCH: Zbliż żebra do miednicy, zaokrąglając górną część tułowia pracą brzucha; wróć powoli.\n\nODDECH: Wydech przy spięciu brzucha, wdech w powrocie.\n\nUNIKAJ: Nie ciągnij ciężaru samymi rękami ani nie wykonuj szarpnięć.";
            case "pallof": return "USTAWIENIE: Ustaw uchwyt mniej więcej na wysokości mostka, stań bokiem do bramy, stopy na szerokość bioder. Napnij brzuch.\n\nRUCH: Trzymaj uchwyt przed klatką, wypchnij ręce na wprost i wróć, nie pozwalając tułowiowi obrócić się do wyciągu.\n\nODDECH: Spokojny wydech przy wypchnięciu, wdech przy powrocie.\n\nUNIKAJ: Nie skręcaj barków ani bioder; zmniejsz opór, jeśli tracisz stabilność.";
            default: return fallback==null?"":fallback;
        }
    }
}
